var oTimer = null;
var oTimerA = null;
var bannerNo = 0;
var bannerCnt = 0;
var bannerNoA = 0;
var bannerCntA = 0;
var banner1Paused = false;
var animationSpeed = 750;
var animateDuration = 5000;

function pauseBanner1() {
    if (oTimerA) {
        clearInterval(oTimerA);
        oTimerA = null;
    }
    banner1Paused = true;
}
function playBanner1() {
    if (!oTimerA && bannerCntA > 0) {
        oTimerA = setInterval("showNextBanner1()", animateDuration);
    }
    banner1Paused = false;
}

function showNextBanner() {
    if (bannerCnt > 0) {
        bannerNo = (bannerNo + 1 >= bannerCnt) ? 0 : bannerNo + 1;
    }
    rollBanner();
}

function showPrevBanner() {
    if (bannerCnt > 0) {
        bannerNo = (bannerNo + 1 >= bannerCnt) ? 0 : bannerNo + 1;
    }
    rollBanner();
}

function showSpecifiedBanner(bNo) {
    bannerNo = bNo;
    rollBanner();
}



function showNextBanner1() {
    if (bannerCntA > 0) {
        bannerNoA = (bannerNoA + 1 >= bannerCntA) ? 0 : bannerNoA + 1;
    }
    rollBanner1();
}

function showPrevBanner1() {
    if (bannerCntA > 0) {
        bannerNoA = (bannerNoA + 1 >= bannerCntA) ? 0 : bannerNoA + 1;
    }
    rollBanner1();
}

function showSpecifiedBanner1(bNoA) {
    bannerNoA = bNoA;
    rollBanner1();
}



function rollBanner() {
    jQuery("#banner_line_wrap a.js_show_image").finish().animate({
        "opacity": "0"
    }, animationSpeed, "swing", function() {
        jQuery("#banner_line_wrap a.js_show_image").css("display", "none");
        jQuery("#banner_line_wrap ul.num > li > a").removeClass("num_on").removeClass("num").addClass("num");
        jQuery("#banner_line_wrap a.js_show_image:eq(" + bannerNo + ")").css({
            "opacity": "0",
            "display": "block"
        });
        jQuery("#banner_line_wrap ul.num > li > a:eq(" + bannerNo + ")").removeClass("num").addClass("num_on");
        jQuery("#banner_line_wrap a.js_show_image:eq(" + bannerNo + ")").animate({
            "opacity": "1"
        }, animationSpeed);
    });
}

function rollBanner1() {
    jQuery("#banner_line_wrap1 div.js_show_image").finish().animate({
        "opacity": "0"
    }, animationSpeed, "swing", function() {
        jQuery("#banner_line_wrap1 div.js_show_image").css("display", "none");
        jQuery("#banner_line_wrap1 ul.num > li > a").removeClass("num_on").removeClass("num").addClass("num");
        jQuery("#banner_line_wrap1 div.js_show_image:eq(" + bannerNoA + ")").css({
            "opacity": "0",
            "display": "block"
        });
        jQuery("#banner_line_wrap1 ul.num > li > a:eq(" + bannerNoA + ")").removeClass("num").addClass(
            "num_on");
        jQuery("#banner_line_wrap1 div.js_show_image:eq(" + bannerNoA + ")").animate({
            "opacity": "1"
        }, animationSpeed);
    });
}

